#!/usr/bin/env bash
# Install EdgeGuardian as a desktop application on the ZGX Nano (DGX OS / Ubuntu):
#   - ./EdgeGuardian            executable launcher (starts the ZRT model server if needed, opens the app window)
#   - ~/.local/share/applications/edgeguardian.desktop   (appears in the application grid / dock)
# Run once after scripts/setup_gb10.sh:   bash scripts/install_gb10.sh
set -euo pipefail
cd "$(dirname "$0")/.."
ROOT="$(pwd)"
cat > EdgeGuardian <<LAUNCHER
#!/usr/bin/env bash
# EdgeGuardian launcher (generated by scripts/install_gb10.sh)
cd "$ROOT"
source .venv-gb10/bin/activate
BASE="\${GUARDIAN_LLM__BASE_URL:-http://127.0.0.1:8080/v1}"
if ! curl -s "\$BASE/models" | grep -q '"id"'; then
  if command -v zrt >/dev/null; then
    mkdir -p runs
    (bash scripts/launch_gb10_llm.sh > runs/zrt_launch.log 2>&1 &)
  fi
fi
exec python -m edge_guardian desktop --profile "\${PROFILE:-gb10}" "\$@"
LAUNCHER
chmod +x EdgeGuardian
mkdir -p runs ~/.local/share/applications ~/.local/share/icons
cp installer/sentinel_256.png ~/.local/share/icons/edgeguardian.png
cat > ~/.local/share/applications/edgeguardian.desktop <<DESKTOP
[Desktop Entry]
Type=Application
Name=EdgeGuardian
Comment=On-device multimodal safety investigator (HP ZGX Nano / GB10)
Exec="$ROOT/EdgeGuardian"
Icon=$HOME/.local/share/icons/edgeguardian.png
Terminal=false
Categories=Utility;Video;
DESKTOP
update-desktop-database ~/.local/share/applications 2>/dev/null || true
# Native window support (WebKitGTK for pywebview) - optional; Chrome/Chromium/Firefox app mode is the fallback.
if command -v apt-get >/dev/null && [[ "${INSTALL_GTK:-1}" == "1" ]]; then
  sudo apt-get install -y python3-gi gir1.2-gtk-3.0 gir1.2-webkit2-4.1 >/dev/null 2>&1 || echo "(WebKitGTK not installed; a chromeless browser window will be used)"
fi
echo "Installed. Launch with ./EdgeGuardian or from the application grid ('EdgeGuardian')."
